"""Regenerate a live server list from the canonical Electrum server directory."""

from __future__ import annotations

import json
import urllib.request
from concurrent.futures import ThreadPoolExecutor

from .electrum import Connection, ElectrumError, Server, parse_server

CANONICAL = (
    "https://raw.githubusercontent.com/spesmilo/electrum/"
    "{ref}/electrum/servers.json"
)

HEADER = """\
# Electrum server list (mainnet).
# Generated by: check-balances --refresh-servers
# Source: canonical Electrum servers.json ({ref}); each entry liveness-probed.
# Format: host:port:ssl or host:port:tcp, one per line.
# 'ssl' = TLS-wrapped (encrypted, but usually self-signed -> not authenticated)
# 'tcp' = plaintext
# '#' comments and blank lines are ignored.
# --
"""


def canonical_candidates(ref: str = "4.5.5", timeout: int = 25) -> list[Server]:
    """Parse the upstream servers.json into candidate endpoints.

    The upstream format is ``{host: {"s": "50002", "t": "50001", ...}}`` where the
    presence of a key means the transport is offered. Onion addresses are skipped;
    reaching them needs a Tor SOCKS proxy this tool does not manage.
    """
    url = CANONICAL.format(ref=ref)
    data = json.loads(urllib.request.urlopen(url, timeout=timeout).read())

    out: list[Server] = []
    seen: set[str] = set()
    for host, spec in data.items():
        if host.endswith(".onion") or not isinstance(spec, dict):
            continue
        for line in (
            f"{host}:{spec.get('s') or 50002}:ssl" if "s" in spec else "",
            f"{host}:{spec.get('t') or 50001}:tcp" if "t" in spec else "",
        ):
            if not line:
                continue
            srv = parse_server(line)
            if srv and srv.key not in seen:
                seen.add(srv.key)
                out.append(srv)
    return out


def probe(srv: Server, timeout: float = 8.0) -> tuple[Server, bool]:
    """Check whether a server answers.

    Connection.connect() already performs the one permitted server.version
    handshake, so liveness is confirmed with server.ping - the protocol rejects a
    second server.version on the same connection ("server.version already done").
    """
    try:
        with Connection(srv, timeout=timeout) as conn:
            conn.ping()
        return srv, True
    except (ElectrumError, OSError):
        return srv, False


def refresh(ref: str = "4.5.5", workers: int = 40) -> list[Server]:
    """Fetch, probe, and return the live subset of the canonical list."""
    cands = canonical_candidates(ref)
    with ThreadPoolExecutor(max_workers=workers) as ex:
        results = list(ex.map(lambda s: probe(s), cands))
    return [srv for srv, ok in results if ok]


def write_list(path: str, servers: list[Server], ref: str = "4.5.5") -> None:
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(HEADER.format(ref=ref))
        for srv in sorted(servers, key=lambda s: s.key):
            fh.write(f"{srv.host}:{srv.port}:{'ssl' if srv.use_tls else 'tcp'}\n")


__all__ = ["canonical_candidates", "probe", "refresh", "write_list"]